def _fuzzy_known_name(name: str, tool_schemas: dict[str, dict[str, Any]]) -> str | None:
    key = _name_key(name)
    if len(key) < 4:
        return None
    matches = get_close_matches(key, [_name_key(known) for known in tool_schemas], n=2, cutoff=0.8)
    if len(matches) != 1:
        return None
